function inspect(result:PaginatedDocument){const root=document.createElement('div');root.innerHTML=result.html;const pages=root.querySelectorAll('.pagedjs_page'),mapped=[...root.querySelectorAll('[data-line]')].map(el=>Number(el.getAttribute('data-line')));return {total:result.total,pageElements:pages.length,text:root.textContent,math:root.querySelectorAll('math').length,svg:root.querySelectorAll('svg').length,images:root.querySelectorAll('img').length,mapped: mapped.length,validMap:mapped.length>0&&mapped.every(line=>Number.isSafeInteger(line)&&line>0&&line<=markdown.split('\n').length),lastMapped:mapped.includes(markdown.split('\n').length),css:result.css.includes('.pagedjs_page'),cssBytes:new TextEncoder().encode(result.css).length}}
